// 15-seo.php — WP Phase 9, C1 (Yoast SEO free, D-046): SEO titles and meta descriptions of the 56 English / Arabic pages,
// the "—" title separator and the Arabic 404 title. Run through Novamira with the data prepended as its first line:
//   $META = json_decode(base64_decode('<scripts/wp/seo-meta.json, base64>'), true);   (file generated by 15-seo-meta.mjs)
// and optionally $DRY = true; (resolves the 56 pages and reports what would change, writes nothing).
// Writes only Yoast fields: per page _yoast_wpseo_metadesc, and _yoast_wpseo_title where the prototype's title differs from
// Yoast's page template "%%title%% %%page%% %%sep%% %%sitename%%" (otherwise the field is left empty so the page title is used);
// the Yoast option "separator"; one Polylang string translation (Arabic) of Yoast's 404 title. Re-running is idempotent.
// After the write each page's Yoast indexable build is triggered. Where Yoast stores indexables (production) this refreshes
// them; in LocalWP's "local" environment it stores none (should_index_indexables false) and builds the output per request.
// Not touched: Elementor data, page titles / slugs, canonical, hreflang (Polylang), any other Yoast or site setting.

if (!isset($META) || !is_array($META) || count($META) !== 56) {
  echo json_encode(['error' => 'META missing or not 56 pages']);
  return;
}

// Published pages by front-end path (both languages share slugs, so the language is part of the key).
$byPath = [];
foreach (get_posts(['post_type' => 'page', 'post_status' => 'publish', 'numberposts' => -1, 'lang' => '', 'suppress_filters' => true]) as $p) {
  $byPath[wp_make_link_relative(get_permalink($p))] = $p;
}

$watcher = YoastSEO()->classes->get(\Yoast\WP\SEO\Integrations\Watchers\Indexable_Post_Watcher::class);
$report = ['pages' => [], 'missing' => []];

foreach ($META as $m) {
  $p = $byPath[$m['path']] ?? null;
  if (!$p || pll_get_post_language($p->ID) !== $m['lang']) {
    $report['missing'][] = $m['path'];
    continue;
  }
  $default = $p->post_title . ' %%sep%% %%sitename%%';
  $title = $m['yoast_title'] === $default ? '' : $m['yoast_title'];
  $before = [get_post_meta($p->ID, '_yoast_wpseo_title', true), get_post_meta($p->ID, '_yoast_wpseo_metadesc', true)];
  if (!empty($DRY)) {
    $report['pages'][] = [$p->ID, $m['path'], $title === '' ? '(template)' : $title, $before !== [$title, $m['description']] ? 'would change' : 'same'];
    continue;
  }
  $title === '' ? delete_post_meta($p->ID, '_yoast_wpseo_title') : update_post_meta($p->ID, '_yoast_wpseo_title', $title);
  update_post_meta($p->ID, '_yoast_wpseo_metadesc', $m['description']);
  $watcher->build_indexable($p->ID);
  $report['pages'][] = [$p->ID, $m['path'], $title === '' ? '(template)' : $title, $before !== [$title, $m['description']] ? 'changed' : 'same'];
}

if (!empty($DRY)) {
  $report['count'] = count($report['pages']);
  echo json_encode($report, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
  return;
}

// Title separator: em dash, as the prototype ("Page — Brand").
WPSEO_Options::set('separator', 'sc-mdash');

// Arabic 404 title: Yoast's option is translated by Polylang (context "wordpress-seo"); prototype ar/404.html title.
$ar = PLL()->model->get_language('ar');
$mo = new PLL_MO();
$mo->import_from_db($ar);
$mo->add_entry($mo->make_entry('Page not found %%sep%% %%sitename%%', 'الصفحة غير موجودة %%sep%% %%sitename%%'));
$mo->export_to_db($ar);

$report['separator'] = WPSEO_Options::get('separator');
$report['count'] = count($report['pages']);
echo json_encode($report, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
